# TEACH AND REPLAY - generated by SPIKE Maze Coder (Pybricks, SPIKE Prime)
from pybricks.hubs import PrimeHub
from pybricks.pupdevices import Motor, UltrasonicSensor
from pybricks.parameters import Port, Direction, Color, Icon, Button, Stop
from pybricks.robotics import DriveBase
from pybricks.tools import wait, StopWatch
import umath

WHEEL = 56          # wheel diameter mm
AXLE = 112           # axle track mm
TURN_FACTOR = 1     # from calibration: real turn / asked turn
CELL = 250           # cell size mm
SPEED = 450          # mm/s
TURN_SPEED = 360     # deg/s
ACCEL = 1500                     # mm/s^2, also used for braking: v^2 = v_end^2 + 2*a*d
FRONT_STOP = 80      # stop this far from a front wall
SIDE_CENTER = 80     # side reading when centred
WALL = 180           # reading below this = wall
OPEN = 230           # reading above this = open
KP = 1.5                         # deg/s turn per mm off-centre

hub = PrimeHub()
left_motor = Motor(Port.B)
right_motor = Motor(Port.E, Direction.COUNTERCLOCKWISE)
robot = DriveBase(left_motor, right_motor, WHEEL, AXLE * TURN_FACTOR)   # axle scaled = turn calibration
robot.settings(straight_speed=SPEED, straight_acceleration=ACCEL, turn_rate=TURN_SPEED, turn_acceleration=2000)
front = UltrasonicSensor(Port.C)
left = UltrasonicSensor(Port.D)
right = UltrasonicSensor(Port.A)


def read(eye, n=3):
    v = sorted([eye.distance() for _ in range(n)])[n // 2]   # median filter
    return 2000 if v <= 0 else v                              # 2000 = nothing in range


def clamp(v, lo, hi):
    return max(lo, min(hi, v))


def centring():
    """turn rate from the side sensors: + = steer right"""
    l, r = read(left, 1), read(right, 1)
    if l < WALL and r < WALL:
        e = (r - l) / 2
    elif r < WALL:
        e = r - SIDE_CENTER
    elif l < WALL:
        e = SIDE_CENTER - l
    else:
        e = 0
    return clamp(KP * e, -80, 80)


def drive(dist_mm):
    """drive a distance (or until a front wall), centred, braking curve, stall check"""
    robot.reset()
    stuck = StopWatch()
    while True:
        to_go = dist_mm - robot.distance()
        f = read(front, 1)
        to_go = min(to_go, f - FRONT_STOP)
        if to_go <= 2:
            break
        v = clamp(umath.sqrt(100 * 100 + 2 * ACCEL * to_go) * 0.9, 100, SPEED)
        robot.drive(v, centring())
        if abs(robot.state()[1]) > 40:
            stuck.reset()
        elif stuck.time() > 600:
            break
        wait(5)
    robot.stop()


def turn(angle):
    robot.stop()
    hub.display.icon(Icon.ARROW_RIGHT if angle > 0 else Icon.ARROW_LEFT)
    robot.turn(angle)
    hub.display.icon(Icon.ARROW_UP)

ASK_EVERY_WALL = False     # True = ask at every front wall, False = only at junctions
DEAD_END_TURN = True        # None = stop at a dead end
MAGIC = 77


def load():
    try:
        d = hub.system.storage(0, read=2)
        if d[0] != MAGIC:
            return None
        n = d[1]
        return list(hub.system.storage(2, read=n)) if n else []
    except Exception:
        return None


def save(choices):
    try:
        hub.system.storage(0, write=bytes([MAGIC, len(choices)] + choices))
    except Exception:
        print("update Pybricks firmware to save choices")


def code_to_angle(c):
    """stored byte: bit0 = right, bit1 = 45 deg"""
    a = 45 if c & 2 else 90
    return a if c & 1 else -a


def wait_choice():
    """wait for LEFT or RIGHT; hold over 0.7 s = 45 deg. Bluetooth button = finished"""
    hub.light.blink(Color.MAGENTA, [200, 200])
    while True:
        p = hub.buttons.pressed()
        if Button.BLUETOOTH in p:
            return None
        if Button.LEFT in p or Button.RIGHT in p:
            right_side = Button.RIGHT in p
            t = StopWatch()
            while hub.buttons.pressed():
                wait(10)
            c = (1 if right_side else 0) | (2 if t.time() > 700 else 0)
            hub.light.on(Color.GREEN)
            return c
        wait(10)


teach = Button.LEFT in hub.buttons.pressed()
stored = None if teach else load()
replay = stored is not None and len(stored) > 0
choices = []
k = 0
hub.light.on(Color.CYAN if replay else Color.GREEN)
print("REPLAY" if replay else "TEACH", "mode")
wait(800)
while True:
    drive(100000)                                # forward until a wall is in front
    l_open = read(left) > OPEN
    r_open = read(right) > OPEN
    junction = l_open and r_open
    if not l_open and not r_open:                # dead end
        if DEAD_END_TURN is None:
            break
        turn(180)
        continue
    if replay:
        if (junction or ASK_EVERY_WALL) and k < len(stored):
            a = code_to_angle(stored[k])
            k += 1
            if (a > 0 and not r_open) or (a < 0 and not l_open):
                a = -a                           # saved side blocked: take the open one
        else:
            a = 90 if r_open else -90
        turn(a)
        continue
    # teach run
    if junction or ASK_EVERY_WALL:
        robot.stop()
        c = wait_choice()
        if c is None:                            # Bluetooth button: finished, save
            break
        choices.append(c)
        save(choices)
        turn(code_to_angle(c))
    else:
        turn(90 if r_open else -90)              # only one way: no question
robot.stop()
if not replay:
    save(choices)
    print("saved", len(choices), "choices")
hub.light.on(Color.BLUE)
hub.display.icon(Icon.HAPPY)
wait(3000)